import { launch } from '/www/server/nodejs/v22.22.2/lib/node_modules/cloakbrowser/dist/index.js';

const url = 'https://mp.weixin.qq.com/s/wdNqnZoof-IWC2VtdN0vFQ';

const browser = await launch({ headless: true });
const page = await browser.newPage();

// Set viewport
await page.setViewport({ width: 1280, height: 800 });

// Navigate to the URL
await page.goto(url, { waitUntil: 'networkidle', timeout: 30000 });

// Wait a bit for any lazy-loaded content
await new Promise(r => setTimeout(r, 3000));

// Take screenshot
await page.screenshot({ path: '/tmp/wechat-article.png', fullPage: true });

// Extract text content
const text = await page.evaluate(() => {
  // Get the article content from the WeChat page
  const richMedia = document.querySelector('#js_content');
  if (richMedia) {
    return richMedia.innerText;
  }

  // Try alternative selectors
  const article = document.querySelector('.rich_media_content');
  if (article) {
    return article.innerText;
  }

  return document.body.innerText;
});

const title = await page.evaluate(() => {
  const titleEl = document.querySelector('#activity-name') || document.querySelector('.rich_media_title') || document.querySelector('title');
  return titleEl ? titleEl.innerText || titleEl.textContent : 'No title found';
});

console.log('=== TITLE ===');
console.log(title);
console.log('=== CONTENT ===');
console.log(text);

await browser.close();

